#!/bin/bash
# server=build.palaso.org
# project=Bloom
# build=Bloom-Default-Continuous
# root_dir=..
# Originally auto-generated by https://github.com/sillsdev/BuildUpdate, but that generator is
# obsolete and we no longer use it: this file is now maintained directly. Edit it by hand.
# See "ReadMe - Updating getDependencies scripts.txt" for how to add or change a dependency.
# The "*** Results ***" comment block below is a leftover of the generated era; it is just
# documentation of where these artifacts come from, so keep it roughly in step with the
# copy_auto lines.

# this has nothing to do with dependencies, but putting it here
# so that it gets run. This allows blame to see through
# commits that are only there to format code.
git config blame.ignoreRevsFile .git-blame-ignore-revs

cd "$(dirname "$0")"

# *** Functions ***
force=0
clean=0

while getopts fc opt; do
case $opt in
f) force=1 ;;
c) clean=1 ;;
esac
done

shift $((OPTIND - 1))

# The dependencies we failed to get. We collect them all rather than dying on the first
# one, because a developer whose network (or build server) is unhappy wants the whole list.
failures=()

# Every file we tried to fetch this run, the ones we borrowed from another worktree rather
# than downloading, and whether any zip failed to unpack. Together these let report_failures
# say what actually matters to the developer: is anything missing, or do we have a complete
# set that we simply could not check for updates?
destinations=()
borrowed=()
extraction_failed=0

# Report one problem now (so it appears next to the download it belongs to) and remember it
# for the summary at the end.
note_failure() {
echo "*** ERROR: $1" >&2
failures+=("$1")
}

# Fail the script if any dependency could not be obtained, with a summary loud enough to
# spot in the middle of init.sh's interleaved parallel output.
report_failures() {
if [ ${#failures[@]} -eq 0 ]
then
return 0
fi
local missing=()
local destination
for destination in "${destinations[@]}"
do
if [ ! -s "$destination" ]
then
missing+=("$destination")
fi
done
echo "" >&2
echo "**********************************************************************" >&2
echo "*** getDependencies-windows.sh FAILED: ${#failures[@]} problem(s):" >&2
for failure in "${failures[@]}"
do
echo "***   $failure" >&2
done
echo "***" >&2
if [ ${#missing[@]} -ne 0 ]
then
echo "*** ${#missing[@]} of ${#destinations[@]} dependencies are MISSING altogether:" >&2
for destination in "${missing[@]}"
do
echo "***   $destination" >&2
done
echo "*** This checkout CANNOT build until those downloads succeed." >&2
else
echo "*** All ${#destinations[@]} dependencies are present on disk even so, so this checkout" >&2
echo "*** can probably still build. What failed was checking them against the server, so" >&2
echo "*** we do not know they are up to date -- which is why this is still a failure." >&2
if [ ${#borrowed[@]} -ne 0 ]
then
echo "*** Note that ${#borrowed[@]} of them we copied from another worktree during this run and" >&2
echo "*** never managed to check against the server at all:" >&2
for destination in "${borrowed[@]}"
do
echo "***   $destination" >&2
done
fi
if [ "$extraction_failed" == "1" ]
then
echo "*** But a zip failed to unpack (see above), so what was extracted from it is" >&2
echo "*** probably incomplete." >&2
fi
fi
echo "***" >&2
echo "*** Nothing was overwritten with whatever the server sent instead, so whatever we" >&2
echo "*** already had is still there and still good." >&2
echo "*** Check https://build.palaso.org and your network, then run this script" >&2
echo "*** (or ./init.sh) again." >&2
echo "**********************************************************************" >&2
exit 1
}

# True if the file starts out looking like an HTML document. TeamCity, and any proxy or
# captive portal between us and it, reports problems with an HTML page -- sometimes even
# with a 200 status. None of our dependencies are HTML, so such a page is always an error
# report we must not mistake for the artifact we asked for.
# (Done with bash's own "read -N" rather than head|grep because in Git Bash on Windows grep
# aborts when fed binary data through a pipe, which would make every check silently pass.)
looks_like_html() {
local start
IFS= read -r -N 1024 start < "$1" || true
start="${start,,}"
case "$start" in
*"<!doctype html"*|*"<html"*|*"<head>"*) return 0 ;;
esac
return 1
}

# The other working trees of this repo (the main checkout plus any git worktrees), as absolute
# paths. Empty until find_sibling_worktrees has run, and empty forever if git can't tell us.
sibling_worktrees=()
sibling_worktrees_known=0

# Fill in sibling_worktrees, once.
find_sibling_worktrees() {
if [ "$sibling_worktrees_known" == "1" ]
then
return 0
fi
sibling_worktrees_known=1
local here
here=$(git -C .. rev-parse --show-toplevel 2>/dev/null) || return 0
local line
local tree
while IFS= read -r line
do
case "$line" in
"worktree "*)
tree="${line#worktree }"
if [ "$tree" != "$here" ] && [ -d "$tree" ]
then
sibling_worktrees+=("$tree")
fi
;;
esac
done < <(git -C .. worktree list --porcelain 2>/dev/null)
}

# These dependencies change rarely, and a developer typically has several worktrees of this
# repo, each of which has already downloaded them. So when we haven't got a file at all
# (a brand new worktree, mostly), copy the newest copy a sibling worktree has, timestamp and
# all, before asking the network for it. That is not a substitute for checking with the
# server: the borrowed timestamp is what the conditional GET in copy_curl then sends, so the
# server still gets to say "that is current" (304, and we saved the whole download) or hand
# us something newer.
# $1 is the URL we are about to download, $2 the file we want.
seed_from_sibling_worktree() {
# with -f the caller wants a fresh download regardless, so there is nothing to save
if [ -e "$2" ] || [ "$force" == "1" ]
then
return 0
fi
find_sibling_worktrees
# our destinations are all "../something"; that "something" is the path within a worktree
local relative="${2#../}"
local candidate
local newest=""
local tree
for tree in "${sibling_worktrees[@]}"
do
candidate="$tree/$relative"
# Only borrow from a worktree that asks for this file from the same place we do. A
# worktree on another branch may well fill the same path from a different build --
# Bloom.chm comes from Bloom_Help_BloomHelp63/64/65 depending on the branch -- and its
# copy, being newer than our artifact, would win the conditional GET below and leave us
# holding the wrong file.
if ! grep -qF -- "copy_auto $1 $2" "$tree/build/getDependencies-windows.sh" 2>/dev/null
then
continue
fi
# Skip anything empty or HTML: an old version of this script, or one interrupted
# mid-download, could have left junk there, and we must not spread it around.
if [ -f "$candidate" ] && [ -s "$candidate" ] && ! looks_like_html "$candidate"
then
if [ -z "$newest" ] || [ "$candidate" -nt "$newest" ]
then
newest="$candidate"
fi
fi
done
if [ -n "$newest" ]
then
echo "copy: $2 <= $newest (already downloaded by another worktree)"
# -p to keep the timestamp, which is what makes the conditional GET meaningful
if cp -p "$newest" "$2"
then
borrowed+=("$2 (from $newest)")
else
rm -f "$2"
fi
fi
}

copy_auto() {
if [ "$clean" == "1" ]
then
echo cleaning $2
rm -f ""$2""
else
destinations+=("$2")
seed_from_sibling_worktree "$1" "$2"
where_curl=$(type -P curl)
where_wget=$(type -P wget)
if [ "$where_curl" != "" ]
then
copy_curl "$1" "$2"
elif [ "$where_wget" != "" ]
then
copy_wget "$1" "$2"
else
echo "Missing curl or wget"
exit 1
fi
fi
}

# Downloads into a temporary file and only replaces the real one once we are happy with what
# arrived. Writing straight to the destination (as this used to) means an error page or a
# truncated transfer becomes, say, our copy of PodcastUtilities.PortableDevices.dll, and the
# C# build then fails with a wildly misleading message.
copy_curl() {
echo "curl: $2 <= $1"
local temp="$2.getDependencies-download"
rm -f "$temp"
local args=(-# -L --fail --retry 2 --connect-timeout 30 -o "$temp" -w '%{http_code}')
if [ -e "$2" ] && [ "$force" != "1" ]
then
# ask for it only if the server's copy is newer than ours
args+=(-z "$2")
fi
local http_code
local status
http_code=$(curl "${args[@]}" "$1")
status=$?
if [ "$status" != "0" ]
then
rm -f "$temp"
note_failure "$2 <= $1: curl failed (exit code $status, HTTP status ${http_code:-none})"
return
fi
if [ "$http_code" == "304" ]
then
# our copy is already up to date; curl sent us no content at all
rm -f "$temp"
return
fi
if [ ! -s "$temp" ]
then
rm -f "$temp"
note_failure "$2 <= $1: the server sent nothing (HTTP status $http_code)"
return
fi
if looks_like_html "$temp"
then
rm -f "$temp"
note_failure "$2 <= $1: the server sent an HTML page (HTTP status $http_code) instead of the file we asked for"
return
fi
if ! mv -f "$temp" "$2"
then
rm -f "$temp"
note_failure "$2 <= $1: downloaded it, but could not put it in place (is something using the old file?)"
fi
}

copy_wget() {
echo "wget: $2 <= $1"
f1=$(basename $1)
f2=$(basename $2)
cd $(dirname $2)
# wget, unlike curl, does not save the body of an error response unless asked to
# (--content-on-error), so a failure here leaves any existing file alone. We just have to
# notice it and say so instead of carrying on as if we had the file.
if ! wget -q -L -N "$1"
then
note_failure "$2 <= $1: wget failed"
cd -
return
fi
# wget has no true equivalent of curl's -o option.
# Different versions of wget handle (or not) % escaping differently.
# A URL query is the only reason why $f1 and $f2 should differ.
if [ "$f1" != "$f2" ]; then mv $f2\?* $f2; fi
cd -
}


